24	// mirrorProbeTimeout bounds the control-plane round-trip when `entire status`
25	// or `entire enable` checks whether this repo is mirrored, so an offline
26	// terminal degrades to StateUnknown instead of hanging.
27	const mirrorProbeTimeout = 5 * time.Second
28	
29	// onboardingRungDeps carries the ground-truth probes the setup rungs check.
30	// Production wiring lives in newOnboardingRungDeps; tests inject fakes so rung
31	// logic runs without keyring, network, or filesystem access.
32	type onboardingRungDeps struct {
33		installedAgents func(ctx context.Context) []string
34		envToken        func() string
35		listContexts    func() ([]*contexts.Context, string, error)
36		tokenForContext func(c *contexts.Context) (string, error)
37		// resolveOrigin parses the origin remote into (forge, owner, repo);
38		// forge is "gh" for github.com (gitremote.ResolveRemoteRepo semantics).
39		resolveOrigin func(ctx context.Context) (forge, owner, repo string, err error)
40		// authed reports whether a usable login exists, without prompting.
41		authed func(ctx context.Context) bool
42		// probeMirror reports whether owner/repo is mirrored on any reachable
43		// core, and whether that mirror is suspended (production: cached,
44		// multi-core — see probeRepoMirrored).
45		probeMirror func(ctx context.Context, owner, repo string) (mirrorProbeResult, error)
46		// discoverImports reports per-agent local history discoverable for this
47		// repo and how much of it has not been imported yet. Local-only.
48		discoverImports func(ctx context.Context) ([]agentImportStatus, error)
49	}
