35	// runOnboardingImport is the import rung's offer, composing the enable-time
36	// import machinery from PR #1595: agent-scoped discovery, the optional
37	// per-agent picker, and best-effort per-agent imports (checkpoint policy and
38	// redaction config are enforced inside runSelectedImports). granular=true
39	// (step-by-step mode) shows the picker — Import/Skip confirm for one agent,
40	// multi-select for several, empty selection skips. granular=false imports
41	// everything eligible: the "set up everything" and --yes paths, where consent
42	// was already given.
43	func runOnboardingImport(ctx context.Context, w io.Writer, granular bool, scope []agent.Agent) error {
44		repoRoot, err := paths.WorktreeRoot(ctx)
45		if err != nil {
46			return fmt.Errorf("resolve worktree root: %w", err)
47		}
48		if scope == nil {
49			scope = installedImportAgents(ctx)
50		}
51		eligible := sessionImportDiscover(ctx, scope, repoRoot)
52		if len(eligible) == 0 {
53			return nil
54		}
55		selected := eligible
56		if granular {
57			selected, err = sessionImportPrompt(ctx, w, eligible)
58			if err != nil {
59				return fmt.Errorf("import selection: %w", err)
60			}
61			if len(selected) == 0 {
62				return nil
63			}
64		}
65		sessionImportRun(ctx, w, repoRoot, selected)
66		return nil
67	}
